INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 18, 'theory', 'Quiz: multipath, iSCSI and FC');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 18, 0, 'Why does a single LUN visible through two paths show up in the system as two disks, such as sdb and sdc?', '["The kernel creates a separate SCSI disk per path, and multipathd joins them by WWID", "The array splits the LUN in two between the paths", "The kernel always mirrors the two paths", "sdc appears only after a reboot"]', 0, 'Every path is a separate SCSI device with its own name. An identical WWID says it is one device, and multipathd builds one map over the paths under /dev/mapper.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 18, 1, 'What does status=enabled on a path group in multipath -ll mean?', '["The group has no usable path", "The administrator has locked the group", "A standby group: it has usable paths, but I/O currently goes through the active group", "The group works together with the active group"]', 2, 'Active is the group carrying I/O, enabled is a standby, disabled has no usable path. Switching depends on failback.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 18, 2, 'All paths of a map failed at time 0. no_path_retry is 12 and polling_interval is 5. What happens to a request arriving at time 30 if no path has returned?', '["It fails at once", "It is queued until time 60 and then fails", "It waits forever", "It is dropped silently without an error"]', 1, 'The number in no_path_retry counts polling intervals of queueing: 12 times 5 seconds is 60. Until the deadline requests wait, then queueing is disabled and they fail.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 18, 3, 'Which setting wins when values of one parameter conflict?', '["defaults", "devices", "overrides", "multipaths for that WWID"]', 3, 'From strongest to weakest: multipaths, overrides, devices, defaults. The multipaths section is tied to an exact WWID and beats even overrides.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 18, 4, 'What does the iSCSI parameter replacement_timeout, 120 seconds by default, set?', '["How long a CHAP password is valid", "How long the kernel waits for the session to return before failing I/O to the application", "The period of target discovery", "The lifetime of a record in the node database"]', 1, 'It is the wait for session recovery. Until it expires I/O stays queued; with multipath it is often lowered to switch to another path sooner.');
